  function escapeHtml(value){return String(value==null?'':value).replace(/[&<>'"]/g,function(ch){return ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[ch];});}
  function cssEscape(value){if(window.CSS&&typeof window.CSS.escape==='function')return window.CSS.escape(String(value));return String(value).replace(/[^a-zA-Z0-9_-]/g,'\\$&');}
  function absoluteUrl(path){try{return new URL(path,CONFIG.siteOrigin||window.location.origin).href;}catch(e){return path;}}
  function formatPrice(value,currency){if(!Number.isFinite(Number(value)))return '';return new Intl.NumberFormat('cs-CZ',{style:'currency',currency:currency||'CZK',maximumFractionDigits:0}).format(Number(value));}
  function iconFor(product){if(product.category==='Gummies')return '●';if(product.category==='Kolageny')return '✦';return '◆';}
  function injectStyles(){if(document.getElementById(STYLE_ID))return;const style=document.createElement('style');style.id=STYLE_ID;style.textContent=CSS_TEXT;style.textContent += MYBEARS_UNIFIED_DESIGN_CSS;
    document.head.appendChild(style);}
  function productTags(p){const tags=[];if(p.vegan===true)tags.push('vegan');if(p.sugarFree===true)tags.push('bez cukru');if(p.glutenFree===true)tags.push('bez lepku');if(p.halal===true)tags.push('halal');if(p.caffeine===true)tags.push('obsahuje stimulanty');return tags;}
  function findJsonLdProduct(value){if(!value)return null;if(Array.isArray(value)){for(let i=0;i<value.length;i+=1){const found=findJsonLdProduct(value[i]);if(found)return found;}return null;}if(typeof value!=='object')return null;const type=value['@type'];if(type==='Product'||(Array.isArray(type)&&type.indexOf('Product')!==-1))return value;if(value['@graph'])return findJsonLdProduct(value['@graph']);return null;}
  async function fetchProductMeta(product){
    if(!CONFIG.enableLiveProductData)return {};
    const url=absoluteUrl(product.url);if(pageCache.has(url))return pageCache.get(url);
    const promise=fetch(url,{credentials:'same-origin',headers:{Accept:'text/html'}}).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.text();}).then(function(html){
      const doc=new DOMParser().parseFromString(html,'text/html');let node=null;
      Array.from(doc.querySelectorAll('script[type="application/ld+json"]')).some(function(script){try{node=findJsonLdProduct(JSON.parse(script.textContent));}catch(e){node=null;}return !!node;});
      const offer=node&&Array.isArray(node.offers)?node.offers[0]:node&&node.offers;let image=node&&node.image;if(Array.isArray(image))image=image[0];if(image&&typeof image==='object')image=image.url||image.contentUrl;
      if(!image){const img=doc.querySelector('[itemprop="image"],.product-image img,.product-detail img,img[data-main-image]');image=img&&(img.getAttribute('src')||img.getAttribute('data-src'));}
      let price=offer&&(offer.price||offer.lowPrice);if(!price){const el=doc.querySelector('[itemprop="price"],.price-final,.product-price,[data-price]');price=el&&(el.getAttribute('content')||el.getAttribute('data-price')||(el.textContent||'').replace(/[^0-9,.-]/g,'').replace(',','.'));}
      const availabilityRaw=offer&&offer.availability?String(offer.availability):'';let availability='';let inStock=null;
      if(/InStock|LimitedAvailability/i.test(availabilityRaw)){availability='Skladem';inStock=true;}else if(/OutOfStock|SoldOut/i.test(availabilityRaw)){availability='Není skladem';inStock=false;}else{const stockEl=doc.querySelector('.availability,[itemprop="availability"],.stock,.product-availability');availability=stockEl?stockEl.textContent.trim().replace(/\s+/g,' '):'';if(availability)inStock=!/není|vyprodáno|nedostup/i.test(availability);}
      return {name:node&&node.name?String(node.name):product.name,image:image?absoluteUrl(image):'',price:Number(price),currency:offer&&offer.priceCurrency?offer.priceCurrency:'CZK',availability:availability,inStock:inStock};
    }).catch(function(error){if(CONFIG.debug&&window.console)console.warn('[MBBB] Live product data failed',product.id,error);return {error:true};});
    pageCache.set(url,promise);return promise;
  }
  function selectionFromHash(){if(!CONFIG.enableShareLink)return [];const match=String(window.location.hash||'').match(/(?:^#|&)balicek=([^&]+)/);if(!match)return [];return decodeURIComponent(match[1]).split(',').filter(function(id){return PRODUCT_MAP.has(id);}).slice(0,CONFIG.maxProducts);}
  function updateHash(ids){if(!CONFIG.enableShareLink)return;const base=window.location.href.split('#')[0];const hash=ids.length?'#balicek='+encodeURIComponent(ids.join(',')):'';try{history.replaceState(null,'',base+hash);}catch(e){}}
